uint32_t fn_01(const uint8_t *in, size_t len, uint32_t arg, uint8_t *out, size_t out_cap)
{
    uint32_t h = 0xFFFFFFFF;
    size_t i;
    for (i = 0; i < len; i++) {
        uint8_t c = in[i];
        h ^= c;
        size_t j;
        for (j = 0; j < 8; j++) {
            h = (h & 1) ? (h >> 1) ^ 0xEDB88320 : h >> 1;
        }
    }
    return ~h;
}
